#!/bin/sh\nset -e\n\nQUOTES_FILE="/app/quotes.txt"\n\nif [ ! -f "$QUOTES_FILE" ]; then\n  echo "Quotes file not found!" >&2\n  exit 1\nfi\n\n# If QUOTE_SEED is set, use it to make the selection deterministic (useful for tests)\nif [ -n "$QUOTE_SEED" ]; then\n  awk -v seed="$QUOTE_SEED" 'BEGIN{srand(seed)} {a[NR]=$0} END{print a[int(rand()*NR)+1]}' "$QUOTES_FILE"\nelse\n  awk 'BEGIN{srand()} {a[NR]=$0} END{print a[int(rand()*NR)+1]}' "$QUOTES_FILE"\nfi\n
